//! The codex app-server protocol, as agentmux speaks it.
//!
//! `codex app-server` speaks JSON-RPC on stdio, one message per line.
//! This crate is what both of agentmux's sides of that conversation share — the driver, which is
//! the client, and the test server that stands in for codex:
//!
//! - [`types`]: the payloads, generated by progeny from the JSON Schema the codex CLI itself
//!   publishes (`codex app-server generate-json-schema`);
//! - [`methods`]: one marker type per method codex lists, named by [`Method`] and directed by a
//!   direction trait; for each method agentmux uses, bound by [`TypedParams`] to its params and,
//!   for a request, by [`TypedResponse`] to the type that answers it; and an `Any*` enum per
//!   direction that classifies an incoming message by its method;
//! - [`envelope`]: the JSON-RPC framing around the payloads, written by hand;
//! - [`exec`]: the events `codex exec --json` writes, which a turn driven over the app-server is
//!   recorded as too; written by hand, because codex publishes no schema for them, and checked
//!   against codex's own types by the generator's oracle;
//! - [`rollout`]: the usage windows codex records in a session rollout, read leniently and
//!   checked by the same oracle.
//!
//! [`types`] and [`methods`] are generated by `crates/codex-app-server-codegen` into
//! `src/generated/` and checked in; that crate's tests fail when they differ from what its
//! vendored schema generates.
//!
//! The types are not taken from codex's own `codex-app-server-protocol` crate, although its
//! licence would allow it, because that crate is part of codex's core rather than a protocol
//! leaf.
//! It resolves only with codex's `[patch.crates-io]` forks, brings several hundred packages with
//! native dependencies such as `aws-lc-sys`, `openssl-sys` and `libdbus-sys`, and builds only
//! against the pins in codex's own lockfile, which a dependent cannot inherit.
//! Generating them adds no dependency beyond `serde` and `serde_json`.

pub mod envelope;
pub mod exec;
pub mod rollout;

// Everything under `src/generated/` is written by crates/codex-app-server-codegen, so what its
// lints would change belongs in the generator; regenerate with `task codegen:app-server`.
mod generated {
    #[rustfmt::skip]
    #[expect(
        clippy::too_many_lines,
        reason = "an `Any*` enum's `classify` and `method` match every method of codex's protocol \
                  in one direction, and splitting them would hide that the match is exhaustive"
    )]
    pub mod methods;
    #[rustfmt::skip]
    #[expect(
        missing_docs,
        clippy::doc_markdown,
        clippy::too_many_lines,
        clippy::struct_field_names,
        clippy::box_collection,
        reason = "rendered by progeny from `codex app-server generate-json-schema`, whose header \
                  lists what it could not represent; fix what these flag in \
                  crates/codex-app-server-codegen"
    )]
    pub mod schema;
}

use std::fmt;
use std::marker::PhantomData;

use serde::Serialize;
use serde::de::DeserializeOwned;
use serde_json::Value;

pub use envelope::DecodeError;
pub use generated::methods;
pub use generated::schema::types;

/// A JSON-RPC method, by its name.
///
/// Implemented only by the marker types in [`methods`], one for each method codex lists.
pub trait Method {
    /// The JSON-RPC method.
    const METHOD: &'static str;
}

/// A method agentmux sends or decodes, and the type of its `params`.
///
/// Implemented for exactly the methods the generator's surface table names, which is what keeps
/// a message from being built with one method and another method's payload, and what keeps the
/// generated types to what agentmux reads.
pub trait TypedParams: Method {
    /// What `params` carries: `()` for a method that carries none, and an `Option` for one whose
    /// parameters may be left out; either is sent without the member when there is nothing.
    type Params: Serialize + DeserializeOwned;

    /// Decode a message's `params`.
    ///
    /// # Errors
    ///
    /// Returns [`DecodeError`] when the payload does not match the generated type.
    fn decode_params(params: &Value) -> Result<Self::Params, DecodeError> {
        envelope::decode(params)
    }
}

/// A method whose messages are requests, which are answered.
pub trait Request: Method {}

/// A request agentmux sends or answers, and the type of the `result` that answers it.
///
/// codex's schema never says what answers a request; the generator's surface table does, and is
/// checked against codex's own Rust at the pinned release.
pub trait TypedResponse: Request + TypedParams {
    /// What `result` carries.
    type Response: Serialize + DeserializeOwned;

    /// Decode the `result` that answers this request.
    ///
    /// # Errors
    ///
    /// Returns [`DecodeError`] when the payload does not match the generated type.
    fn decode_response(result: &Value) -> Result<Self::Response, DecodeError> {
        envelope::decode(result)
    }
}

/// A method whose messages are notifications, which are not answered.
pub trait Notification: Method {}

/// A request the client sends and the server answers.
pub trait ClientRequest: Request {}

/// A notification the client sends.
pub trait ClientNotification: Notification {}

/// A request the server sends and the client answers.
pub trait ServerRequest: Request {}

/// A notification the server sends.
pub trait ServerNotification: Notification {}

/// The `params` of a message of method `M`, not yet decoded.
///
/// The generated `Any*` enums in [`methods`] classify a message by its method alone and hold its
/// parameters in this, so a receiver matches every method exhaustively but decodes only the
/// payloads it acts on, and can only decode them as the type its method binds.
pub struct RawParams<'a, M> {
    params: &'a Value,
    method: PhantomData<fn() -> M>,
}

impl<'a, M: TypedParams> RawParams<'a, M> {
    /// The `params` of a message of method `M`.
    ///
    /// Nothing is checked until [`RawParams::decode`], which is what decides whether they are
    /// `M`'s.
    #[must_use]
    pub fn new(params: &'a Value) -> Self {
        Self {
            params,
            method: PhantomData,
        }
    }

    /// Decode the parameters into the type `M` binds.
    ///
    /// # Errors
    ///
    /// Returns [`DecodeError`] when the payload does not match the generated type.
    pub fn decode(self) -> Result<M::Params, DecodeError> {
        M::decode_params(self.params)
    }

    /// The parameters as they arrived, `null` when absent.
    #[must_use]
    pub fn raw(self) -> &'a Value {
        self.params
    }
}

impl<M> Clone for RawParams<'_, M> {
    fn clone(&self) -> Self {
        *self
    }
}

impl<M> Copy for RawParams<'_, M> {}

impl<M: Method> fmt::Debug for RawParams<'_, M> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("RawParams")
            .field("method", &M::METHOD)
            .field("params", self.params)
            .finish()
    }
}
